timeout 110 bash -c 'npm run prepare-tests && npm run build && node --input-type=module <<'\''NODE'\''
import { mkdir } from '\''node:fs/promises'\'';
process.env.CREW_DATA_DIR='\''data/w2-work-proof'\'';
const runtime=await import(new URL('\''./scripts/acceptance-runtime.mjs'\'','\''file://'\''+process.cwd()+'\''/'\''));
const people=await import(new URL('\''./scripts/checks/people.mjs'\'','\''file://'\''+process.cwd()+'\''/'\''));
const work=await import(new URL('\''./scripts/checks/work.mjs'\'','\''file://'\''+process.cwd()+'\''/'\''));
const checks=[],ids={};
let server=await runtime.startServer();
try {
 const ctx=runtime.createContext(server.url,ids,checks);
 await ctx.signup('\''owner'\'',{name:'\''Acceptance Owner'\'',email:'\''owner-work-proof@crew.test'\'',password:'\''acceptance long password'\''});
 await people.smoke(ctx);await work.smoke(ctx);await runtime.persist('\''acceptance-state.json'\'',ids);
} finally {await server.stop();}
server=await runtime.startServer();
try {
 const ctx=runtime.createContext(server.url,ids,checks,{readOnly:true});
 await people.restart(ctx);await work.restart(ctx);await work.remount(ctx);await work.audit({checks});
} finally {await server.stop();}
console.log(JSON.stringify({ok:true,pass:checks.length,checks}));
NODE
'

